package ai.patnub.assistant

enum class RedFlagCategory { CARDIAC_RESPIRATORY, NEUROLOGICAL, BLEEDING_GI, ALLERGIC_REACTION }

data class RedFlag(val category: RedFlagCategory, val phrase: String)

/**
 * Pre-LLM emergency screen (Spec §4.4). Runs before retrieval or generation; a match means
 * the Assistant shows the emergency card and never calls the model. Plain substring checks
 * keep it well under the 20 ms budget.
 *
 * Phrases come from [RedFlagRules] (generated by content/build.py): "verified" ones appear word
 * for word in MedlinePlus or FDA label text; "unverified" ones are everyday and Tagalog/Taglish
 * wordings pending clinician review. Both are active: a false alarm is safer than a miss.
 */
object RedFlagGate {
    private val phrases: List<Pair<RedFlagCategory, String>> =
        (RedFlagRules.verified.entries + RedFlagRules.unverified.entries)
            .flatMap { (category, list) -> list.map { category to it } }

    /** First red flag found in [text] (English, Tagalog or Taglish), or null. */
    fun check(text: String): RedFlag? {
        val t = text.lowercase().replace('’', '\'').replace(Regex("\\s+"), " ")
        return phrases.firstOrNull { it.second in t }?.let { RedFlag(it.first, it.second) }
    }
}
